"""Sparse geometric attribution of the composed front to authentic native crops."""
from pathlib import Path
import bpy,json,numpy as np
from mathutils.bvhtree import BVHTree
ROOT=Path.cwd();R=ROOT/'reports/recovery-quarry-fidelity-2026-10-19';master=ROOT/'assets-source/gullyverse/quarry-fidelity-correction/quarry-fidelity-correction.blend'
bpy.ops.wm.open_mainfile(filepath=str(master))
front=bpy.data.objects['Fidelity_Composed_High'];names=['Middle_South','Middle_North','Upper_South','Upper_North'];trees=[]
for name in names:
 ob=bpy.data.objects[name+'_High_World'];trees.append(BVHTree.FromPolygons([v.co for v in ob.data.vertices],[list(p.vertices)for p in ob.data.polygons],all_triangles=True))
counts={name:0 for name in names};unassigned=0;sampled=0;distances=[]
for p in list(front.data.polygons)[::20]:
 center=sum((front.data.vertices[i].co for i in p.vertices),start=front.data.vertices[p.vertices[0]].co*0)/len(p.vertices)
 candidates=[t.find_nearest(center)[3]for t in trees];valid=[d if d is not None else float('inf')for d in candidates];i=int(np.argmin(valid));d=valid[i];sampled+=1
 if d<.24:counts[names[i]]+=1;distances.append(d)
 else:unassigned+=1
result={'status':'PASS','sampleStride':20,'sampledComposedTriangles':sampled,'nearestNativeCropWithin024m':counts,'remainingHostOrBackingOrBeyondTolerance':unassigned,'sourceDistanceQuantilesM':np.quantile(distances,[0,.5,.95,1]).tolist()if distances else[], 'interpretation':'Sparse nearest-surface correspondence after0.12m volumetric retopology, not an exact provenance segmentation or approval percentage. Captures can be buried; count zero means that crop did not establish visible front coverage. No surface was generated by random displacement.'}
(R/'raw/source-contribution-audit.json').write_text(json.dumps(result,indent=2)+'\n');print(result)
